//${AOs::SystemCheck::SM::active::peristalticPump_Check} .....................
static QState SystemCheck_peristalticPump_Check(SystemCheck * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::SystemCheck::SM::active::peristalticPump_Check}
        case Q_ENTRY_SIG: {
            me->Wdata->_state = SYSTEMCHECK_STATE_PUMP;    //蠕动泵自检
            me->_timcnt = 0;
            // bsp_step_motor_ResetPos(me->motor); //清空编码器值
            me->_enpos = bsp_step_motor_GetPosition(me->motor);
            QTimeEvt_armX(&me->_timEvt, 100, 100U);  //启动定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::SystemCheck::SM::active::peristalticPump_Check}
        case Q_EXIT_SIG: {
            me->Wdata->_prstate = SYSTEMCHECK_STATE_PUMP;
            bsp_step_motor_Rotate(me->motor,0);
            QTimeEvt_disarm(&me->_timEvt);
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::SystemCheck::SM::active::peristalticPump_~::TIMEOUT}
        case TIMEOUT_SIG: {
            me->_timcnt++;
            //${AOs::SystemCheck::SM::active::peristalticPump_~::TIMEOUT::[first]}
            if (me->_timcnt == 1) {
                bsp_step_motor_Rotate(me->motor,51200);    //电机往上移动一圈确定电机好坏
                status_ = Q_HANDLED();
            }
            //${AOs::SystemCheck::SM::active::peristalticPump_~::TIMEOUT::[target]}
            else if (me->_timcnt == 16) {
                if(bsp_step_motor_IsEncodePositionInRange(me->motor,me->_enpos+45000,me->_enpos+75000))
                {
                    me->Wdata->checkStatus._pump = 0;    //蠕动泵自检正常
                }
                else
                {
                    me->Wdata->checkStatus._pump = 1;   //蠕动泵自检异常
                }
                // bsp_step_motor_Rotate(me->motor,0);
                LOG_E("Pump Encoder Pos is :%d",bsp_step_motor_GetEncodePosition(me->motor));
                status_ = Q_TRAN(&SystemCheck_valve_Check);
            }
            //${AOs::SystemCheck::SM::active::peristalticPump_~::TIMEOUT::[else]}
            else {
                status_ = Q_HANDLED();
            }
            break;
        }
        default: {
            status_ = Q_SUPER(&SystemCheck_active);
            break;
        }
    }
    return status_;
}

