//${AOs::SystemCheck::SM::active::vaccum_Check} ..............................
static QState SystemCheck_vaccum_Check(SystemCheck * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::SystemCheck::SM::active::vaccum_Check}
        case Q_ENTRY_SIG: {
            me->Wdata->_state = SYSTEMCHECK_STATE_VACCUM;    //灌注阀检测
            me->_timcnt = 0;
            QTimeEvt_armX(&me->_timEvt, 100, 100U);  //启动定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::SystemCheck::SM::active::vaccum_Check}
        case Q_EXIT_SIG: {
            me->Wdata->_prstate = SYSTEMCHECK_STATE_VACCUM;
            QTimeEvt_disarm(&me->_timEvt);
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::SystemCheck::SM::active::vaccum_Check::TIMEOUT}
        case TIMEOUT_SIG: {
            if(bsp_ad7730_readraw(ad7730)>=4500000&&bsp_ad7730_readraw(ad7730)<=5800000)
            {
                me->Wdata->checkStatus._vaccumModule = 0;    //灌注阀门正常
            }
            else
            {
                me->Wdata->checkStatus._vaccumModule = 1;    //灌注阀异常
            }
            LOG_E("Vaccum Raw value  is :%d",bsp_ad7730_readraw(ad7730));
            status_ = Q_TRAN(&SystemCheck_Dia_Check);
            break;
        }
        default: {
            status_ = Q_SUPER(&SystemCheck_active);
            break;
        }
    }
    return status_;
}


