static QState SystemCheck_Dia_CheckIO1(SystemCheck * const me, QEvt const * const e) {
    
        QState status_;
        switch (e->sig)
        {
            //${AOs::SystemCheck::SM::active::vaccum_Check}
            case Q_ENTRY_SIG: {
                me->Wdata->_state = SYSTEMCHECK_STATE_DIAIO1;    //灌注阀检测
                me->_timcnt = 0;
                QTimeEvt_armX(&me->_timEvt, 50, 50U);  //启动定时器
                bsp_dia_test_io(0,0);   //关闭PWRIO观察是否有输出
                status_ = Q_HANDLED();
                break;
            }
            case Q_EXIT_SIG: {
                me->Wdata->_prstate = SYSTEMCHECK_STATE_DIAIO1;
                bsp_dia_test_io(0,1); 
                QTimeEvt_disarm(&me->_timEvt);
                status_ = Q_HANDLED();
                break;
            }
            case TIMEOUT_SIG: {
                // if(bsp_get_valve(I_ADC_CH)>=300)
                if(bsp_get_valve(I_ADC_CH)>=43690)  //???????
                {
                    me->Wdata->checkStatus._diathermy |= 1;    //电凝异常
                    Diathermy_Task_SetPwr(0);
                    status_ = Q_TRAN(&SystemCheck_motor_Check);
                }
                else
                {
                    me->Wdata->checkStatus._diathermy |= 0;    //电凝正常
                    status_ = Q_TRAN(&SystemCheck_Dia_CheckIO2);
                }
//                LOG_E("Diathermy Raw value  is :%d",bsp_get_valve(I_ADC_CH));
                // status_ = Q_TRAN(&SystemCheck_Dia_CheckIO2);
                break;
            }
            default: {
                status_ = Q_SUPER(&SystemCheck_active);
                break;
            }
        }
}
