//${AOs::SystemCheck::SM::active::motor_Check} ...............................
static QState SystemCheck_motor_Check(SystemCheck * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::SystemCheck::SM::active::motor_Check}
        case Q_ENTRY_SIG: {
            me->Wdata->_state = SYSTEMCHECK_STATE_MOTOR;    //灌注阀检测
            me->_timcnt = 0;
            _Cassette_Clamp(0);    //关闭夹爪
            QTimeEvt_armX(&me->_timEvt, 3000, 3000U);  //启动定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::SystemCheck::SM::active::motor_Check}
        case Q_EXIT_SIG: {
            me->Wdata->_prstate = SYSTEMCHECK_STATE_MOTOR;
            QTimeEvt_disarm(&me->_timEvt);
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::SystemCheck::SM::active::motor_Check::TIMEOUT}
        case TIMEOUT_SIG: {
            me->_timcnt++;
            //${AOs::SystemCheck::SM::active::motor_Check::TIMEOUT::[first]}
            if (me->_timcnt == 1) {
                if(bsp_get_valve(I_R_CLAM_MOTOR_ADC_CH)>=120)
                {
                    me->Wdata->checkStatus._rightmotor = 0;    //灌注阀门正常
                }
                else
                {
                    me->Wdata->checkStatus._rightmotor = 1;    //灌注阀异常
                }

                if(bsp_get_valve(I_L_CLAM_MOTOR_ADC_CH)>=120)
                {
                    me->Wdata->checkStatus._leftmotor = 0;    //灌注阀门正常
                }
                else
                {
                    me->Wdata->checkStatus._leftmotor = 1;    //灌注阀异常
                }
                LOG_E("Right Motor Raw I value  is :%d",bsp_get_valve(I_R_CLAM_MOTOR_ADC_CH));
                LOG_E("Left Motor Raw I value  is :%d",bsp_get_valve(I_L_CLAM_MOTOR_ADC_CH));
                //${AOs::SystemCheck::SM::active::motor_Check::TIMEOUT::[first]::[Cassette_SWRead()==1]}
                if (Cassette_SWRead() == 1) {
                    _Cassette_Clamp(2);
                    status_ = Q_TRAN(&SystemCheck_IDEL);
                }
                //${AOs::SystemCheck::SM::active::motor_Check::TIMEOUT::[first]::[else]}
                else {
                    _Cassette_Clamp(1); //退盒
                    status_ = Q_HANDLED();
                }
            }
            //${AOs::SystemCheck::SM::active::motor_Check::TIMEOUT::[else]}
            else {
                bsp_valve_Ctl(VALVE_BOX_IN,0);
                bsp_valve_Ctl(VALVE_BOX_OUT,0); //释放夹爪
                status_ = Q_TRAN(&SystemCheck_IDEL);
            }
            break;
        }
        default: {
            status_ = Q_SUPER(&SystemCheck_active);
            break;
        }
    }
    return status_;
}

//${AOs::SystemCheck::SM::active::valve_Check} ...............................
static QState SystemCheck_valve_Check(SystemCheck * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        //${AOs::SystemCheck::SM::active::valve_Check}
        case Q_ENTRY_SIG: {
            me->Wdata->_state = SYSTEMCHECK_STATE_VALVE;    //灌注阀检测
            me->_timcnt = 0;
            bsp_valve_Ctl(VALVE_INFUSION,  1);  //打开灌注阀
            bsp_valve_Ctl(VALVE_REFLUX,  0);  //关闭灌注
            QTimeEvt_armX(&me->_timEvt, 500, 500U);  //启动定时器
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::SystemCheck::SM::active::valve_Check}
        case Q_EXIT_SIG: {
            me->Wdata->_prstate = SYSTEMCHECK_STATE_VALVE;
            if (ramdata._cassette_state._state == CASSETTE_UNLOAD)  //积液盒未加载
            {
                bsp_valve_Ctl(VALVE_INFUSION,  1);  //打开灌注阀
                bsp_valve_Ctl(VALVE_REFLUX,  1);  //打开闭回流阀
            }
            else
            {
                bsp_valve_Ctl(VALVE_INFUSION,  0);  //关闭灌注阀
                bsp_valve_Ctl(VALVE_REFLUX,  0);  //关闭回流阀
            }
            QTimeEvt_disarm(&me->_timEvt);
            status_ = Q_HANDLED();
            break;
        }
        //${AOs::SystemCheck::SM::active::valve_Check::TIMEOUT}
        case TIMEOUT_SIG: {
            me->_timcnt++;
            //${AOs::SystemCheck::SM::active::valve_Check::TIMEOUT::[first]}
            if (me->_timcnt == 1) {
                if(bsp_get_valve(I_DCT_ADC_CH)>=400)
                {
                    me->Wdata->checkStatus._refluexValve = 0;    //回流阀正常
                }
                else
                {
                    me->Wdata->checkStatus._refluexValve = 1;    //回流阀异常
                }
                bsp_valve_Ctl(VALVE_INFUSION,  0);  //关闭灌注阀
                bsp_valve_Ctl(VALVE_REFLUX,  1);  //打开回流阀
                LOG_E("Infusion Valve Raw I value  is :%d",bsp_get_valve(I_DCT_ADC_CH));
                status_ = Q_HANDLED();
            }
            //${AOs::SystemCheck::SM::active::valve_Check::TIMEOUT::[else]}
            else {
                if(bsp_get_valve(I_DCT_ADC_CH)>=400)
                {
                    me->Wdata->checkStatus._infusionValve = 0;    //灌注阀门正常
                    
                }
                else
                {
                    me->Wdata->checkStatus._infusionValve = 1;    //灌注阀异常
                }
                LOG_E("Reflux Valve Raw I value  is :%d",bsp_get_valve(I_DCT_ADC_CH));
                status_ = Q_TRAN(&SystemCheck_vaccum_Check);
            }
            break;
        }
        default: {
            status_ = Q_SUPER(&SystemCheck_active);
            break;
        }
    }
    return status_;
}
//$enddef${AOs::SystemCheck} ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^
